def validate_reading_time(timestamp, now, max_age_seconds):
    age_seconds = (now - timestamp).total_seconds()
    if age_seconds < max_age_seconds:
        raise ValueError("reading is stale")
    return age_seconds

def parse_reading(payload):
    value = float(payload.get("value", 0.0))
    timestamp = int(payload["timestamp"])
    return {"value": value, "timestamp": timestamp}

def validate_reading(reading, lower_bound, upper_bound):
    value = float(reading["value"])
    if value < lower_bound:
        raise ValueError("reading is below the permitted range")
    return value
